(function () {
  'use strict';
  const D=window.PHARM_DATA, E=window.PharmEngine, KEY='pharmnote:v1';
  const app=document.getElementById('app'), dialog=document.getElementById('dialog');
  if(!D||!E){app.innerHTML='<div class="loading"><h1>앱 파일을 확인해 주세요.</h1><p>dist 폴더의 파일을 함께 두고 index.html을 열어 주세요.</p></div>';return;}
  const cards=new Map(D.cards.map(c=>[c.id,c])), questions=new Map(D.questions.map(q=>[q.id,q]));
  const chapters=new Map(D.chapters.map(c=>[c.id,c])), sources=new Map(D.sources.map(s=>[s.id,s]));
  let storageOK=true, state=E.emptyState(), loadMessage='', draft={}, confirmAction=null, toastTimer;
  try {const saved=localStorage.getItem(KEY);if(saved) state=E.restore(JSON.parse(saved),D);} catch {storageOK=false;loadMessage='저장된 기록을 읽지 못했습니다. 이 창에서는 계속 학습할 수 있습니다.';}
  const settings={chapters:D.chapters.map(c=>c.id),type:'all',count:10};
  const library={query:'',chapter:'all',bookmarks:false};
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
  const btn=(label,action,cls='primary',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
  const sourceRef=source=>`<button class="source-ref" data-action="source" data-source="${source.fileId}" data-pages="${source.pages.join(',')}">${icon('file')}<span>${esc(sources.get(source.fileId).filename)} · PDF p.${source.pages.join(', ')}</span></button>`;
  const typeName=t=>t==='match'?'약물·MOA·용도 매칭':'A/B 설명 판정';
  const dateFormat=at=>new Intl.DateTimeFormat('ko-KR',{month:'short',day:'numeric'}).format(new Date(at));
  const footer=()=>`<footer class="site-footer"><span>강의자료 기반 학습용 · 임상적 처방이나 복약 안내가 아닙니다.</span><span>기록은 이 브라우저에 저장됩니다 · <a href="#sources">자료·기록 관리</a></span></footer>`;
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('기록을 저장하지 못했습니다. 자료·기록에서 백업을 내려받아 주세요.');}}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
  function route(){const path=location.hash.slice(1);return ['home','library','review','sources','quiz','results'].includes(path)?path:'home';}
  function go(path){if(route()===path){render();window.scrollTo(0,0);}else location.hash=path;}
  function showDialog(title,body,accept=null,acceptLabel='확인'){
    confirmAction=accept;
    dialog.innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}<div class="button-row">${btn(accept?'취소':'닫기','close-dialog','secondary')}${accept?btn(acceptLabel,'confirm-dialog'):''}</div>`;
    if(!dialog.open)dialog.showModal();
  }
  function makeSession(config){
    const proceed=()=>{const session=E.createSession(D,config);if(!session){toast('선택한 범위에 문제가 없습니다. 범위를 다시 선택해 주세요.');return;}state.session=session;draft={};save();go('quiz');};
    if(state.session&&!state.session.completedAt)showDialog('새 퀴즈를 시작할까요?','<p>진행 중인 퀴즈는 종료됩니다. 이미 푼 문제의 학습 기록과 오답은 유지됩니다.</p>',proceed,'새로 시작');
    else proceed();
  }
  function render(options={}){
    let page=route();
    if(page==='quiz'&&(!state.session||state.session.completedAt))page=state.session?.completedAt?'results':'home';
    if(page==='results'&&!state.session?.completedAt)page='home';
    const active=['quiz','results'].includes(page)?'home':page;
    const nav=[['home','grid','학습 홈'],['library','cards','약물 카드'],['review','book','오답노트'],['sources','file','자료·기록']];
    app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home" aria-label="약리노트 학습 홈"><img src="./icon.svg" alt=""><div><strong>약리노트</strong><small>PHARM NOTE</small></div></a><div class="nav-caption">MY STUDY</div><nav class="nav" aria-label="주 메뉴">${nav.map(([id,i,label])=>`<a href="#${id}" ${active===id?'aria-current="page"':''} class="${active===id?'active':''}">${icon(i)}<span>${label}</span>${id==='review'?`<span class="count">${E.wrongIds(state).length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-note">${icon('spark')}<strong>하나씩, 확실하게.</strong><p>이름과 기전이 연결되는 순간,<br>약리학이 조금 더 쉬워져요.</p></div><div class="profile"><span class="avatar">P</span><div><strong>나의 학습 공간</strong><small>로그인 없이 바로 학습</small></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">내 학습 공간<span>/</span><strong>약리학 기말</strong></div><button class="search-shortcut" data-action="search">${icon('search')}<span>약물 찾아보기</span><kbd>/</kbd></button></header><main id="main" tabindex="-1">${!storageOK?'<div class="storage-warning" role="status">학습 기록의 영구 저장이 제한되어 있습니다. 종료 전에 자료·기록에서 백업해 주세요.</div>':''}${({home:renderHome,library:renderLibrary,review:renderReview,sources:renderSources,quiz:renderQuiz,results:renderResults}[page])()}${footer()}</main></div></div>`;
    if(options.focusId)document.getElementById(options.focusId)?.focus({preventScroll:true});
  }
  function heading(eyebrow,title,text,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${text}</p></div>${extra}</div>`;}
  function renderHome(){
    const st=E.stats(state,D), pool=E.pool(D,settings), wrong=E.wrongIds(state).length;
    const complete=state.session&&!state.session.completedAt;
    const today=new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(new Date());
    return `${heading('A LITTLE EVERY DAY','오늘도, 하나씩 연결해요','약물의 이름, 작용기전, 용도를 나만의 속도로 익혀보세요.',`<span class="date-label">${today}</span>`)}${complete?`<div class="resume-banner"><div><strong>풀던 퀴즈가 있어요</strong><small>${state.session.items.filter(i=>i.selection!==null).length} / ${state.session.items.length}문제 완료</small></div>${btn('이어서 풀기 '+icon('arrow'),'resume','secondary small')}</div>`:''}<section class="hero" aria-label="학습 소개"><div class="hero-content"><span class="hero-tag">${icon('book')} 약리학 기말 · CH.10–26</span><h2>외우는 약리학에서,<br><em>연결하는 약리학으로.</em></h2><p>6개의 강의자료, ${D.cards.length}개의 약물 카드.<br>매칭과 A/B 판정으로 기억을 더 단단하게.</p></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="art-line"></div><div class="art-line two"></div><div class="art-card drug"><span class="symbol">Rx</span><div><small>START WITH</small><strong>약물명</strong></div></div><div class="art-card moa"><span class="symbol">◎</span><div><small>HOW IT WORKS</small><strong>MOA</strong></div></div><div class="art-card use"><span class="symbol">↗</span><div><small>WHAT IT DOES</small><strong>용도</strong></div></div><div class="art-dot"></div></div></section><div class="dashboard-grid"><section class="panel panel-pad" id="quiz-settings" aria-labelledby="config-title"><div class="panel-header"><h2 id="config-title">오늘의 퀴즈 만들기</h2><span class="overline">YOUR OWN PACE</span></div><div class="step-label"><span>1</span>어떤 방식으로 공부할까요?</div><div class="type-options"><button class="type-button ${settings.type!=='ab'?'selected':''}" data-action="type" data-value="match" aria-pressed="${settings.type!=='ab'}"><span class="type-icon">${icon('link')}</span><span><strong>약물·MOA·용도 매칭</strong><small>이 약물은 어떻게, 어디에?<br>세 가지를 연결해요.</small></span></button><button class="type-button ${settings.type!=='match'?'selected':''}" data-action="type" data-value="ab" aria-pressed="${settings.type!=='match'}"><span class="type-icon">${icon('cards')}</span><span><strong>A/B 설명 판정</strong><small>두 설명을 꼼꼼히 읽고<br>옳고 그름을 판단해요.</small></span></button></div><label class="blend"><input type="checkbox" id="blend" ${settings.type==='all'?'checked':''}>두 유형을 섞어서 풀기</label><div class="step-label"><span>2</span>학습 범위를 골라주세요</div><div class="section-choices">${btn('전체 범위','scope','chip '+(settings.chapters.length===17?'selected':''),'data-source="all"')}${D.sources.map(s=>btn(`Ch.${s.chapters[0]}–${s.chapters.at(-1)}`,'scope','chip '+(settings.chapters.length===s.chapters.length&&s.chapters.every(c=>settings.chapters.includes(c))?'selected':''),`data-source="${s.id}"`)).join('')}</div><details class="chapter-select" id="chapter-details"><summary>장별로 선택하기 · ${settings.chapters.length}개 장 선택</summary><div class="chapter-grid">${D.chapters.map(c=>`<label class="chapter-check"><input type="checkbox" data-chapter="${c.id}" ${settings.chapters.includes(c.id)?'checked':''}>Ch.${c.id} ${c.title}</label>`).join('')}</div></details><div class="config-bottom"><div><div class="step-label"><span>3</span>몇 문제를 풀까요?</div><div class="count-options">${[10,20,30,'all'].map(n=>btn(n==='all'?'전체':`${n}문제`,'count','count-button '+(settings.count===n?'selected':''),`data-value="${n}" aria-pressed="${settings.count===n}"`)).join('')}</div><div class="pool-label">선택 범위 ${settings.chapters.length?pool.length:0}문제 · ${settings.chapters.length?(settings.count==='all'?pool.length:Math.min(settings.count,pool.length)):0}문제 출제</div></div>${btn('퀴즈 시작하기 '+icon('arrow'),'start','primary',!settings.chapters.length||!pool.length?'disabled':'')}</div></section><aside class="dashboard-aside"><section class="panel panel-pad"><div class="panel-header"><h2>나의 학습 현황</h2><span class="overline">PROGRESS</span></div><div class="stat-ring" style="--value:${st.accuracy}%"><div class="stat-ring-inner"><strong>${st.attempts?st.accuracy+'<span style="font-size:15px">%</span>':'—'}</strong><small>누적 정답률</small></div></div><div class="stat-pairs"><div><strong>${st.answered}</strong><small>학습한 문제</small></div><div><strong>${D.questions.length}</strong><small>전체 문제</small></div></div><p class="stat-note">${st.attempts?`${st.attempts}회 풀이 · ${st.correct}회 정답`:'첫 퀴즈를 풀고 기록을 쌓아보세요.'}</p></section><section class="review-callout">${icon('book')}<h3>${wrong?`${wrong}문제, 다시 만나볼까요?`:'틀려도 괜찮아요.'}</h3><p>${wrong?'헷갈렸던 연결을 한 번 더.<br>맞히면 오답노트에서 사라져요.':'틀린 문제는 자동으로 모아둘게요.<br>다시 풀면서 확실하게 익혀요.'}</p><button data-action="go-review">오답노트 펼치기 ${icon('arrow')}</button></section></aside></div><section class="materials"><div class="section-heading"><h2>강의자료별로 학습하기</h2><p>6개 자료 · 145페이지 · ${D.chapters.length}개 장</p></div><div class="source-grid">${D.sources.map(s=>{const count=D.cards.filter(c=>s.chapters.includes(c.chapter)).length;return `<button class="source-tile" data-action="source-study" data-source="${s.id}"><span class="source-number">${icon('file')}</span><div><div class="mini-label">CHAPTER ${s.chapters[0]}—${s.chapters.at(-1)}</div><h3>${s.label}</h3><small>${count}개 카드 · ${count*2}문제</small></div></button>`;}).join('')}</div></section>`;
  }
  function option(question,item,kind,index,position){
    const selected=item.selection||draft, answered=item.selection!==null;
    const answer=question.type==='ab'?question.answer:question[kind].answer;
    const chosen=selected[kind]===index, correct=answered&&answer===index, wrong=answered&&chosen&&answer!==index;
    const label=question.type==='ab'?E.AB_LABELS[index]:question[kind].choices[index];
    return `<button id="option-${kind}-${index}" class="answer-option ${chosen?'selected ':''}${correct?'correct ':''}${wrong?'wrong':''}" data-action="select-answer" data-kind="${kind}" data-value="${index}" aria-pressed="${chosen}" ${answered?'disabled':''}><span class="answer-letter">${position+1}</span><span>${esc(label)}</span>${correct?'<span class="answer-state">정답</span>':wrong?'<span class="answer-state">내 선택</span>':''}</button>`;
  }
  function bookmarkButton(id){return btn(icon('star'),'bookmark','icon-button '+(state.bookmarks.includes(id)?'bookmarked':''),`data-card="${id}" aria-label="${state.bookmarks.includes(id)?'저장 해제':'약물 저장'}" aria-pressed="${state.bookmarks.includes(id)}"`);}
  function renderQuiz(){
    const s=state.session,item=s.items[s.index],q=questions.get(item.questionId),card=cards.get(q.cardId),answered=item.selection!==null;
    const n=s.items.filter(i=>i.selection!==null).length;
    return `<div class="quiz-container" data-question-id="${q.id}"><div class="quiz-top"><button class="subtle-link" data-action="leave-quiz">← 학습 홈</button><span class="quiz-count"><strong>${s.index+1}</strong> / ${s.items.length}</span><span class="streak">${icon('flame')} ${s.streak} 연속 정답</span></div><div class="progress-track" role="progressbar" aria-label="퀴즈 진행" aria-valuemin="0" aria-valuemax="${s.items.length}" aria-valuenow="${n}"><span style="width:${n/s.items.length*100}%"></span></div><section class="panel quiz-panel"><div class="quiz-meta"><div><span class="tag">CH.${q.chapter} ${chapters.get(q.chapter).title}</span> <span class="tag purple">${q.type==='match'?'매칭':'A/B 판정'}</span></div>${bookmarkButton(card.id)}</div><h1 class="quiz-question">${q.type==='match'?'이 약물의 기전과 용도를 연결해 보세요.':'A와 B, 옳은 설명을 모두 골라보세요.'}</h1><p class="quiz-instruction">${q.type==='match'?'MOA와 용도를 하나씩 선택하세요. 두 연결이 모두 맞으면 정답입니다.':'각 설명의 참·거짓을 판단하고, 해당하는 조합 하나를 선택하세요.'}</p>${q.type==='match'?`<div class="drug-target"><div class="target-icon">${icon('link')}</div><div><small>DRUG NAME</small><strong>${esc(card.name)}${card.nameKo?`<span>${esc(card.nameKo)}</span>`:''}</strong></div></div><div class="match-columns"><section aria-labelledby="moa-heading"><h2 class="match-heading" id="moa-heading"><span class="number-label">01</span> 작용기전 · MOA</h2><div class="answers">${item.moaOrder.map((index,pos)=>option(q,item,'moa',index,pos)).join('')}</div></section><section aria-labelledby="use-heading"><h2 class="match-heading" id="use-heading"><span class="number-label">02</span> 용도 · USE</h2><div class="answers">${item.useOrder.map((index,pos)=>option(q,item,'use',index,pos)).join('')}</div></section></div>`:`<div class="ab-statements"><div class="statement"><b>A</b><p>${esc(q.a)}</p></div><div class="statement"><b>B</b><p>${esc(q.b)}</p></div></div><div class="ab-choices" aria-label="A/B 판정 선택지">${E.AB_LABELS.map((_,index)=>option(q,item,'ab',index,index)).join('')}</div>`}${answered?`<div class="feedback ${item.correct?'':'is-wrong'}" role="status"><div class="feedback-heading">${icon(item.correct?'check':'book')}${item.correct?'정확하게 연결했어요!':'한 번 더 연결해 볼까요?'}</div>${q.type==='ab'?`<div class="truth-row"><span class="truth-label">A · ${q.truth[0]?'옳음':'틀림'}</span><span class="truth-label">B · ${q.truth[1]?'옳음':'틀림'}</span></div>`:`<div class="truth-row"><span class="truth-label">MOA · ${item.selection.moa===q.moa.answer?'정답':'오답'}</span><span class="truth-label">용도 · ${item.selection.use===q.use.answer?'정답':'오답'}</span></div>`}<p>${esc(q.explanation)}</p>${sourceRef(q.source)}</div>`:''}<div class="quiz-actions"><small>${answered?(item.correct?'학습 기록에 저장했어요.':'오답노트에 저장했어요.'):(q.type==='ab'?'숫자 1–4로 선택 · Enter로 채점':'각 열에서 하나씩 선택한 뒤 채점하세요.')}</small>${answered?btn((s.index===s.items.length-1?'결과 보기':'다음 문제')+' '+icon('arrow'),'next','primary','id="next-button"'):btn('정답 확인하기 '+icon('check'),'submit','primary',`id="submit-button" ${E.validSelection(q,draft)?'':'disabled'}`)}</div></section><p class="quiz-footer">진행 상황은 자동 저장돼요. 잠깐 쉬었다가 이어서 풀어도 괜찮아요.</p></div>`;
  }
  function filteredCards(){const term=library.query.trim().toLocaleLowerCase();return D.cards.filter(c=>(library.chapter==='all'||c.chapter===Number(library.chapter))&&(!library.bookmarks||state.bookmarks.includes(c.id))&&(!term||[c.name,c.nameKo,c.drugClass,c.moa,c.uses].join(' ').toLocaleLowerCase().includes(term)));}
  function renderDrugCards(){
    const list=filteredCards();
    return `<div class="library-results-label">${list.length}개 카드${library.bookmarks?' · 저장한 약물':''}</div>${list.length?`<div class="drug-grid">${list.map(c=>{const count=D.questions.filter(q=>q.cardId===c.id&&state.progress[q.id]?.lastCorrect).length;return `<article class="panel drug-card"><div class="drug-card-top"><div><span class="tag">CH.${c.chapter}</span><h2>${esc(c.name)}</h2><div class="ko-name">${esc(c.nameKo||'')}</div></div>${bookmarkButton(c.id)}</div><p class="class-label">${esc(c.drugClass)}</p><details><summary>기전·용도 펼치기</summary><dl class="drug-fact"><dt>MECHANISM OF ACTION</dt><dd>${esc(c.moa)}</dd></dl><dl class="drug-fact"><dt>USES</dt><dd>${esc(c.uses)}</dd></dl>${c.caution?`<dl class="drug-fact caution"><dt>기억할 포인트</dt><dd>${esc(c.caution)}</dd></dl>`:''}${sourceRef(c.source)}</details><div class="card-quiz"><span>${count} / 2문제 정답</span>${btn('이 약물 퀴즈 '+icon('arrow'),'card-quiz','subtle-link',`data-card="${c.id}"`)}</div></article>`;}).join('')}</div>`:empty('cards','아직 해당하는 카드가 없어요','검색어나 장 선택을 바꿔보세요. 카드의 별을 누르면 저장한 약물만 모아볼 수 있어요.')}`;
  }
  function renderLibrary(){return `${heading('YOUR DRUG LIBRARY','약물 카드','약물명으로 찾고, 기전과 용도를 한눈에 정리해요.')}<div class="library-toolbar"><label class="search-input-wrap">${icon('search')}<span class="sr-only">약물명·기전·용도 검색</span><input class="search-input" id="drug-search" type="search" placeholder="약물명, 기전, 용도 검색…" value="${esc(library.query)}" autocomplete="off"></label><label><span class="sr-only">장 선택</span><select class="filter-select" id="library-chapter"><option value="all">전체 장</option>${D.chapters.map(c=>`<option value="${c.id}" ${String(c.id)===library.chapter?'selected':''}>Ch.${c.id} ${c.title}</option>`).join('')}</select></label>${btn(icon('star')+' 저장한 약물','filter-bookmarks','chip '+(library.bookmarks?'selected':''),`aria-pressed="${library.bookmarks}"`)}</div><div id="library-results">${renderDrugCards()}</div>`;}
  function empty(i,title,text,action=''){return `<div class="panel empty-state"><div class="empty-icon">${icon(i)}</div><h2>${title}</h2><p>${text}</p>${action}</div>`;}
  function renderReview(){
    const list=E.wrongIds(state).map(id=>questions.get(id)).filter(Boolean);
    return `${heading('MAKE IT STICK','오답노트','헷갈렸던 문제를 다시 풀며, 느슨했던 연결을 단단하게.')}<div class="review-toolbar"><p>복습할 문제 <strong>${list.length}개</strong> · 다시 맞히면 자동으로 제외돼요.</p>${btn('오답 다시 풀기 '+icon('arrow'),'review-all','primary',!list.length?'disabled':'')}</div>${list.length?`<div class="review-list">${list.map(q=>{const c=cards.get(q.cardId),p=state.progress[q.id];return `<article class="panel review-item"><div><div class="item-meta"><span class="tag">CH.${q.chapter}</span><span class="tag purple">${typeName(q.type)}</span></div><h3>${esc(c.name)}</h3><p>${p.attempts}회 풀이 · ${dateFormat(p.lastAt)} 최근 학습</p></div>${btn('다시 풀기 '+icon('arrow'),'review-one','secondary small',`data-question="${q.id}"`)}</article>`;}).join('')}</div>`:empty('check','복습할 오답이 없어요',E.stats(state,D).attempts?'차근차근 잘하고 있어요. 새로운 범위에도 도전해 보세요.':'먼저 퀴즈를 풀어보세요. 틀린 문제는 이곳에 자동으로 모아둘게요.',btn('퀴즈 풀러 가기 '+icon('arrow'),'go-home'))}`;
  }
  function renderResults(){
    const s=state.session,correct=s.items.filter(i=>i.correct).length,wrong=s.items.filter(i=>!i.correct).length;
    const elapsed=Math.max(1,Math.round((s.completedAt-s.startedAt)/60000));
    return `<div class="quiz-container">${heading('ONE STEP FURTHER','오늘의 연결, 완료!','맞힌 문제도, 헷갈린 문제도 모두 다음 학습의 밑거름이에요.')}<section class="panel result-hero"><div class="result-medallion">${icon(correct===s.items.length?'spark':'check')}</div><h1>${correct===s.items.length?'모든 연결이 정확해요!':'한 걸음 더 익숙해졌어요.'}</h1><p>${esc(s.title)} · ${s.items.length}문제</p><div class="result-score">${Math.round(correct/s.items.length*100)}<span> 점</span></div><div class="result-stats"><div><strong>${correct}<small> / ${s.items.length}</small></strong><small>정답</small></div><div><strong>${s.bestStreak}</strong><small>최대 연속 정답</small></div><div><strong>${elapsed}<small>분</small></strong><small>경과 시간</small></div></div><div class="button-row">${wrong?btn(`${wrong}개 오답 다시 풀기`,'retry-session'):''}${btn('새 퀴즈 만들기','go-home','secondary')}</div></section><div class="section-heading"><h2>문제별 학습 기록</h2><p>문제를 펼치면 해설을 볼 수 있어요.</p></div><div class="result-list">${s.items.map((item,index)=>{const q=questions.get(item.questionId),c=cards.get(q.cardId);const chosen=q.type==='ab'?`내 선택: ${E.AB_LABELS[item.selection.ab]}\n정답: ${E.AB_LABELS[q.answer]}`:`내 MOA: ${q.moa.choices[item.selection.moa]}\n내 용도: ${q.use.choices[item.selection.use]}\n정답 MOA: ${q.moa.choices[q.moa.answer]}\n정답 용도: ${q.use.choices[q.use.answer]}`;return `<details class="panel result-item"><summary><span class="result-badge ${item.correct?'':'bad'}">${icon(item.correct?'check':'close')}</span><span>${index+1}. ${esc(c.name)}</span><span class="tag">${q.type==='ab'?'A/B':'매칭'}</span></summary>${q.type==='ab'?`<div class="selected-summary">A. ${esc(q.a)}\nB. ${esc(q.b)}</div>`:''}<div class="selected-summary">${esc(chosen)}</div><p class="explanation">${esc(q.explanation)}</p>${sourceRef(q.source)}</details>`;}).join('')}</div></div>`;
  }
  function renderSources(){return `${heading('YOUR STUDY DESK','자료·기록','문제의 출처를 확인하고, 소중한 학습 기록을 보관하세요.')}<div class="data-layout"><div><div class="sources-list">${D.sources.map(s=>`<article class="panel source-item">${icon('file')}<div><h3>${esc(s.filename)}</h3><p>Ch.${s.chapters[0]}–${s.chapters.at(-1)} · ${s.label}</p><small>원본 ${s.pages}페이지 · ${D.cards.filter(c=>c.source.fileId===s.id).length}개 약물 카드</small></div></article>`).join('')}</div><div class="info-note">각 해설의 페이지는 <strong>PDF 뷰어에서 1부터 세는 페이지 번호</strong>입니다. 이 앱은 제공된 자료의 주요 약물을 선별한 복습용 문제집으로, 원본 전체를 대체하지 않습니다. 원본 PDF는 앱이나 저장소에 포함하지 않았습니다.<br><br>실시간 AI 생성이나 외부 API를 사용하지 않습니다. 미리 검토한 문제를 무료로 반복 학습할 수 있습니다.</div>${state.history.length?`<section class="panel panel-pad" style="margin-top:20px"><h2>최근 퀴즈 기록</h2><table class="history-table"><caption class="sr-only">최근 완료한 퀴즈</caption><thead><tr><th scope="col">날짜</th><th scope="col">퀴즈</th><th scope="col">정답</th></tr></thead><tbody>${state.history.slice(0,10).map(h=>`<tr><td>${dateFormat(h.at)}</td><td>${esc(h.title)}</td><td>${h.correct} / ${h.total}</td></tr>`).join('')}</tbody></table></section>`:''}</div><section class="panel panel-pad data-panel"><div class="panel-header"><h2>나의 기록 관리</h2>${icon('cards')}</div><p>풀이 기록, 오답, 저장한 약물은 <strong>현재 브라우저</strong>에 저장돼요. 다른 기기로 옮기거나 브라우저 데이터를 지우기 전에 백업해 주세요.</p>${btn(icon('download')+' 학습 기록 내보내기','export','secondary wide')}${btn(icon('file')+' 학습 기록 가져오기','import','secondary wide')}<p style="font-size:10px;margin-top:10px">백업 파일(.json)을 가져오면 현재 기록을 교체합니다. 로그인이나 서버 저장은 사용하지 않아요.</p><button class="danger-button" data-action="reset">학습 기록 초기화</button></section></div>`;}
  document.addEventListener('click',event=>{
    const target=event.target.closest('[data-action]');if(!target||target.disabled)return;
    const {action}=target.dataset;
    if(action==='close-dialog'){dialog.close();confirmAction=null;return;}
    if(action==='confirm-dialog'){const fn=confirmAction;confirmAction=null;dialog.close();fn?.();return;}
    if(action==='type'){settings.type=target.dataset.value;render();}
    else if(action==='scope'){settings.chapters=target.dataset.source==='all'?D.chapters.map(c=>c.id):[...sources.get(target.dataset.source).chapters];render();}
    else if(action==='count'){settings.count=target.dataset.value==='all'?'all':Number(target.dataset.value);render();}
    else if(action==='start'){if(settings.chapters.length)makeSession({...settings,title:settings.type==='all'?'매칭 + A/B 혼합 퀴즈':typeName(settings.type)});}
    else if(action==='resume'){draft={};go('quiz');}
    else if(action==='go-home'||action==='leave-quiz')go('home');
    else if(action==='go-review')go('review');
    else if(action==='search'){go('library');setTimeout(()=>document.getElementById('drug-search')?.focus(),30);}
    else if(action==='source-study'){settings.chapters=[...sources.get(target.dataset.source).chapters];if(route()==='home')render();else go('home');document.getElementById('quiz-settings')?.scrollIntoView({behavior:'smooth',block:'start'});toast(`Ch.${settings.chapters[0]}–${settings.chapters.at(-1)} 범위를 선택했어요.`);}
    else if(action==='select-answer'){draft[target.dataset.kind]=Number(target.dataset.value);render({focusId:target.id});}
    else if(action==='submit'){if(E.answer(state,D,draft)){save();render();document.querySelector('.feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});document.getElementById('next-button')?.focus({preventScroll:true});}}
    else if(action==='next'){if(E.next(state)){draft={};save();if(state.session.completedAt)go('results');else{render();window.scrollTo({top:0,behavior:'smooth'});document.querySelector('.quiz-question')?.setAttribute('tabindex','-1');document.querySelector('.quiz-question')?.focus({preventScroll:true});}}}
    else if(action==='bookmark'){
      const id=target.dataset.card;if(!cards.has(id))return;
      const added=!state.bookmarks.includes(id);state.bookmarks=added?[...state.bookmarks,id]:state.bookmarks.filter(c=>c!==id);save();
      if(route()==='library'&&library.bookmarks)document.getElementById('library-results').innerHTML=renderDrugCards();
      else {target.classList.toggle('bookmarked',added);target.setAttribute('aria-pressed',String(added));target.setAttribute('aria-label',added?'저장 해제':'약물 저장');}
      toast(added?'약물 카드에 저장했어요.':'저장을 해제했어요.');
    }
    else if(action==='filter-bookmarks'){library.bookmarks=!library.bookmarks;render();}
    else if(action==='card-quiz'){const ids=D.questions.filter(q=>q.cardId===target.dataset.card).map(q=>q.id);makeSession({questionIds:ids,count:'all',title:cards.get(target.dataset.card).name+' 복습'});}
    else if(action==='review-all')makeSession({questionIds:E.wrongIds(state),count:'all',title:'오답 복습'});
    else if(action==='review-one')makeSession({questionIds:[target.dataset.question],count:'all',title:'오답 복습'});
    else if(action==='retry-session')makeSession({questionIds:state.session.items.filter(i=>!i.correct).map(i=>i.questionId),count:'all',title:'이번 퀴즈 오답 복습'});
    else if(action==='source'){const s=sources.get(target.dataset.source);showDialog('문제의 출처',`<p><strong>${esc(s.filename)}</strong><br>PDF ${esc(target.dataset.pages.split(',').join(', '))}페이지 / 전체 ${s.pages}페이지<br><br>페이지는 PDF 뷰어의 1부터 세는 번호입니다. 제공한 원본 자료에서 해당 페이지를 확인해 주세요.</p>`);}
    else if(action==='export'){
      const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
      a.href=url;a.download=`pharmnote-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('학습 기록을 백업했어요.');
    }
    else if(action==='import')document.getElementById('import-file').click();
    else if(action==='reset')showDialog('학습 기록을 초기화할까요?','<p>풀이 기록, 오답노트, 저장한 약물, 진행 중인 퀴즈가 삭제됩니다. 필요한 기록은 먼저 내보내기로 보관해 주세요.</p>',()=>{state=E.emptyState();draft={};save();render();toast('학습 기록을 초기화했어요.');},'초기화');
  });
  document.addEventListener('change',event=>{
    const target=event.target;
    if(target.id==='blend'){settings.type=target.checked?'all':'match';render();}
    if(target.dataset.chapter){const id=Number(target.dataset.chapter);settings.chapters=target.checked?[...new Set([...settings.chapters,id])]:settings.chapters.filter(c=>c!==id);render();document.getElementById('chapter-details').open=true;document.querySelector(`[data-chapter="${id}"]`)?.focus({preventScroll:true});}
    if(target.id==='library-chapter'){library.chapter=target.value;document.getElementById('library-results').innerHTML=renderDrugCards();}
  });
  document.addEventListener('input',event=>{if(event.target.id==='drug-search'){library.query=event.target.value;document.getElementById('library-results').innerHTML=renderDrugCards();}});
  document.getElementById('import-file').addEventListener('change',async event=>{
    const file=event.target.files[0];event.target.value='';if(!file)return;
    if(file.size>5*1024*1024){toast('5MB 이하의 학습 기록 파일을 선택해 주세요.');return;}
    try {const imported=E.restore(JSON.parse(await file.text()),D);showDialog('백업 기록을 가져올까요?',`<p>현재 기록을 교체합니다.<br>불러올 기록: 학습한 문제 ${Object.keys(imported.progress).length}개, 저장한 약물 ${imported.bookmarks.length}개</p>`,()=>{state=imported;draft={};save();render();toast('학습 기록을 가져왔어요.');},'가져오기');}
    catch {toast('올바른 약리노트 백업 파일이 아닙니다. 현재 기록은 유지됩니다.');}
  });
  document.addEventListener('keydown',event=>{
    if(dialog.open||event.ctrlKey||event.metaKey||event.altKey||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;
    if(event.key==='/'){event.preventDefault();go('library');setTimeout(()=>document.getElementById('drug-search')?.focus(),30);return;}
    if(route()!=='quiz'||!state.session||state.session.completedAt)return;
    const item=state.session.items[state.session.index],q=questions.get(item.questionId);
    if(!item.selection&&q.type==='ab'&&['1','2','3','4'].includes(event.key)){event.preventDefault();draft.ab=Number(event.key)-1;render({focusId:`option-ab-${draft.ab}`});}
    if(event.key==='Enter'&&(document.activeElement?.tagName!=='BUTTON'||document.activeElement?.classList.contains('answer-option'))){const target=document.getElementById(item.selection?'next-button':'submit-button');if(target&&!target.disabled){event.preventDefault();target.click();}}
  });
  window.addEventListener('hashchange',()=>{draft={};render();window.scrollTo(0,0);document.getElementById('main')?.focus({preventScroll:true});});
  render();if(loadMessage)toast(loadMessage);
})();
